('安全环保管理', '基础工作', '监督检查', '3.是否开展日常、经常性、综合性、季节性、节前安全检查；是否建立检查记录和问题整改记录（厂级安全检查每月不得少于一次；车间级（有车间建制的）安全检查每周组织一次）；是否对政府、上级、第三方各类安全检查发现的问题制订有效措施，并按期完成整改。', '重要', 1),
('安全环保管理', '基础工作', '安全观察与沟通', '4.是否制定年度安全观察与沟通计划并录入到HSE信息系统；各级领导及管理人员是否按规定频次实施安全观察与沟通，并及时录入到HSE信息系统；本单位主要领导的安全观察与沟通记录表及上月安全观察与沟通计划执行情况是否进行公示；对存在的问题是否统计、分析并制定相应的管理措施；对记录中现场未整改的事项是否进行跟踪，整改后是否对相应内容进行更新；是否存在其他未按制度要求执行的情况。', '观察', 1),
('安全环保管理', '基础工作', '体系管理', '5.是否建立适用的职业健康安全法律法规及其他要求清单，是否识别具体条款、是否进行动态更新；是否定期开展合规性评价；是否对违反法规情况进行原因分析，制定实施纠正措施。', '一般', 1),
('安全环保管理', '基础工作', '体系管理', '6.针对各级审核中发现的问题，是否按照要求分析原因制定实施纠正措施并填写“不符合、纠正和预防措施实施记录”，完成不符合整改。是否对纠正措施的有效性进行跟踪验证；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '基础工作', 'HSE标准化建设', '7.是否按要求制定标准化建设推进方案；是否制定标准化验收标准；是否开展自评验收；创建完成后是否编制HSE标准化创建总结。', '一般', 1),
('安全环保管理', '基础工作', '安全生产记分管理', '8.各单位是否成立安全生产记分管理工作小组；对在生产安全事故事件、事故隐患或者其他安全生产责任追究中受到行政处分的责任人，是否依据安全生产记分标准进行安全生产记分；根据当年记分情况采取的处理措施是否有效落实；是否存在其他未按制度要求执行的情况。', '重要', 1),
