('安全环保管理', '基础工作', '台账资料', '10.安全管理基础资料台账是否齐全、完善、及时、真实。', '观察', 1),
('安全环保管理', '安全生产责任制', '岗位安全生产职责', '1.是否组织建立岗位HSE职责及责任清单。是否组织岗位HSE职责及责任评审。岗位HSE职责及责任清单是否与实际岗位相符、内容是否有缺失。安全责任制清单中承诺人是否签字，各级领导承诺是否公示。是否动态修订岗位HSE职责及责任清单。', '重要', 1),
('安全环保管理', '安全生产责任制', '岗位安全生产职责', '2.是否熟悉、清楚本岗位HSE职责及责任清单内容。是否认真履行岗位HSE职责及责任清单内容。对各级人员岗位HSE职责及责任清单履职情况是否定期进行考核和兑现。', '一般', 1),
('安全环保管理', '安全生产责任制', '岗位安全生产职责', '3.逐级逐层签订HSE目标责任书，目标合理、符合实际、具体量化。是否及时填写“兰州石化公司QHSE目标完成情况季度检查表”。', '重要', 1),
('安全环保管理', '安全生产责任制', '岗位安全生产职责', '4.是否熟悉熟悉本岗位相关安全制度标准。是否熟悉本岗位或业务范围内的HSE风险和控制措施。是否与承包商签订安全合同，明确各自安全生产职责；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '安全生产责任制', '有感领导', '5.三级以上领导干部是否按要求制订、公布个人安全行动计划。是否落实个人安全行动计划。是否按规定频次深入生产现场实施安全观察与沟通。', '一般', 1),
('安全环保管理', '安全生产责任制', '有感领导', '6.是否定期深入基层进行安全生产监督检查。各级行政正职是否按要求讲授安全课。运行部（分厂）主要负责人是否主持HSE委员会会议。是否按规定要求在主持会议时带头开展安全经验分享。分厂和区域（车间）领导是否按规定参加班组安全学习。分厂和区域（车间）领导是否定期进行安全生产述职。', '观察', 1),
