('安全环保管理', '风险防控', '生产安全风险管理', '1.是否成立风险评价小组，职责是否明确。小组成员是否包括相关管理和专业技术人员。评价小组成员是否掌握危险源辨识与风险评价方法。是否定期组织开展全面的危害因素辨识。', '观察', 1),
('安全环保管理', '风险防控', '生产安全风险管理', '2.是否建立危害因素辨识调查表，建立工艺操作清单、设备设施清单、施工作业清单，建立管理活动清单，形成风险防控评价表，辨识结果是否齐全、充分、无遗漏；是否存在其他未按制度要求执行的情况。', '重要', 1),
('安全环保管理', '风险防控', '生产安全风险管理', '3.是否建立专业生产安全风险汇总表，建立风险防控报告；专业管理部门是否监督本专业各层级风险防控措施落实情况；是否将风险评价结果及控制措施向员工进行宣传、培训；员工是否掌握重大风险及控制措施。', '一般', 1),
('安全环保管理', '风险防控', '生产安全风险管理', '4.发生变更时，是否重新进行危险源辨识；是否动态修订补充完善四个清单和六个风险防控评价表；是否组织开展风险研判；是否按要求及时上报；是否按要求进行公示；是否存在其他未按制度要求执行的情况。', '观察', 1),
('安全环保管理', '安全教育培训', '培训取证', '1.主要负责人和专职安全管理技术人员是否经培训取得安全管理资格证书上岗。', '重要', 1),
('安全环保管理', '安全教育培训', '安全教育', '2.是否有效落实制度要求，开展各类安全教育培训；各级安全教育时间、内容是否符合规定要求，是否考核合格取得安全作业证；每年是否组织一次全员安全考试，成绩是否填入安全作业证（安全上岗证）、安全教育台账；二级单位机关部门、班组是否按期开展安全活动（包括安全学习、环保学习和应急演练等）；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '安全教育培训', '安全教育', '3.各级管理人员是否参加班组安全活动，班组安全学习频次和时间是否符合要求；安全活动是否有内容、有讨论、有记录、有检查、有评语；参加人是否与实际人员相符，缺席者是否进行补学；员工是否掌握近期安全活动记录内容；班组在班前会是否进行安全讲话；各级领导干部和管理人员是否利用安全观察与沟通，向员工讲解相关的安全制度规定等；日常会议、培训班、应急演练、班组安全活动、交接班前是否开展安全经验分享。', '观察', 1),
('安全环保管理', '安全教育培训', '安全教育', '4.是否对外来施工人员进行安全教育；是否进行安全技术交底；培训时间是否符合制度要求；教育存档资料是否齐全、完整、准确。', '重要', 1),
('安全环保管理', '安全教育培训', '安全环保履职能力评估', '5.是否制定了年度工作计划或实施方案、年度工作总结；是否成立安全环保履职考评领导小组和工作小组；是否组织在职和变动到关键岗位的人员进行安全环保履职能力评估；是否对评估结果进行运用；是否存在其他未按制度要求执行的情况。各级人员每年继续教育时间是否符合制度要求。', '一般', 1),
('安全环保管理', '管理与监控', '危险化学品重大危险源管理', '1.是否按照《重大危险源辨识》（GB18218）标准辨识确定重大危险源，是否按要求评估分级，并登记建档；重大危险源是否配备温度、压力、液位、流量、组分等信息的不间断采集系统及可燃气体和有毒有害气体泄漏检测报警装置；涉及毒性气体、液化气体、剧毒液体的一二级重大危险源是否设立SIS系统。', '重要', 1),
('安全环保管理', '管理与监控', '危险化学品重大危险源管理', '2.重大危险源是否建立健全安全监测监控体系，制定完善控制措施；是否按要求进行报告并录入HSE系统；是否定期全面检查重大危险源的安全状况；是否设置明显的安全警示标志和告知牌；是否将事故后果及应急措施告知周边人员；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '管理措施', '危险化学品重大危险源安全包保责任制（安全生产承包点）管理办法', '3.根据承包点安全风险等级，是否明确对应的承包人；重大危险源安全警示标志位置是否设立安全包保公示牌；承包人是否按照检查督导计划到承包点开展检查督导。', '一般', 1),
('安全环保管理', '管理措施', '危险化学品重大危险源安全包保责任制（安全生产承包点）管理办法', '4.公示牌是否写明重大危险源的主要负责人、技术负责人、操作负责人姓名、对应的安全包保职责及联系方式；在非重大危险源的安全生产承包点是否设立“安全生产承包点公示牌”；是否对包保责任人（承包人）履职情况进行定期监督检查；是否将重大危险源的包保、承包点的检查督导计划和履职记录录入HSE信息系统；是否存在其他未按制度要求执行的情况。', '观察', 1),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '1.危险化学品是否有符合相关规范要求的安全技术说明书与安全标签；危险化学品从业人员是否按要求取得相应资质。员工是否清楚日常安全使用、储存等要求，是否掌握消防、应急处置措施；在易燃、易爆场所禁止使用非防爆工具和移动通讯器具；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '2.是否建立危险化学品档案；是否编制危险化学品反应矩阵表。安全现状评价提出问题是否制定整改计划。安全现状评价提出问题是否按计划整改。是否对员工定期进行培训。员工是否了解和掌握学品危险特性；是否存在其他未按制度要求执行的情况。', '观察', 1),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '3.涉及“重点监管的化工工艺”装置是否实现自动化控制、系统是否实现紧急停车功能，并确保投用；危险化学品的生产、使用、储存场所是否设置监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施；生产、储存危险化学品的单位是否在作业场所和安全设施、设备上设置明显的安全警示标志；是否存在其他未按制度要求执行的情况。', '重要', 1),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '4.剧毒品是否对数量、流向、储存量和用途如实记录，并采取安保措施；危险化学品是否储存在专用仓库内，有专人管理，出入库时是否进行核查登记；性质相抵触、灭火方法不同的危险化学品是否分开存放；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '危险化学品安全管理', '防止硫化氢中毒安全管理', '5.有可能泄漏硫化氢造成中毒的装置或区域,是否安装固定式硫化氢报警仪，配备相应的应急器材及有效防护用具，并确保其完好备用；在含硫化氢的装置、设施、设备、管线区域附近是否设置醒目的硫化氢警示牌。', '一般', 1),
('安全环保管理', '危险化学品安全管理', '三乙基铝安全管理', '6.三乙基铝贮罐是否储存在阴凉、干燥、通风良好的库房内；三乙基铝贮罐是否远离火种、热源，防止阳光直射；三乙基铝贮罐是否与其它可燃、易燃物质混放；三乙基铝贮罐安全附件是否完好；储存、使用三乙基铝的单位，对已经入库的三乙基铝贮罐是否建立管理台帐，详细记录使用情况，并指定专人定期检查；三乙基铝储存库房及配制区是否配备足够的专用干粉灭火器、干砂子、蛭石灭火材料；是否存在其他未按制度要求执行的情况。', '重要', 1),
('安全环保管理', '危险化学品安全管理', '防硫化亚铁自燃安全管理', '7.易产生硫化亚铁的常压储罐，条件允许时是否设置氮封；易产生硫化亚铁的浮顶罐操作浮盘是否置底；易产生硫化亚铁的储罐是否按照规定及时切水；可能产生硫化亚铁的装置长期停工，是否采取加盲板密闭，注入氮气置换空气等措施，防止硫化亚铁的产生；易产生硫化亚铁的储罐呼吸阀、检尺采样孔等部位是否每半年清理一次；可能产生硫化亚铁的装置和场所是否制定防止硫化物自燃的措施；是否存在其他未按制度要求执行的情况。', '重要', 1),
('安全环保管理', '危险化学品安全管理', '危险化学品装卸安全管理', '8.进入装卸区域的车辆是否安装阻火器，对位后车头是否朝向出口方向；进站车辆车速是否在5公里/小时之内，是否携带杂物，进站车辆只允许乘坐司机和押运员两人；进站后是否按指定地点进行停放并熄火、用手闸制动；司机是否离开现场，有斜坡是否加固定块；装卸过程中是否严格执行岗位装卸操作规程；装卸人员和押运人员是否在现场；作业完毕封闭罐盖后是否静置不少于2分钟后拆除静电接地线；是否在站内乱排乱放、修理车辆；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '危险化学品安全管理', '危险化学品安全管理', '9.易燃易爆介质装卸过程中是否使用防爆工具；是否使用非防爆通讯工具和非防爆电子产品。', '一般', 1),
('安全环保管理', '生产安全事故隐患管理', '隐患排查', '1.是否至少每周组织一次专业隐患排查；是否至少每月组织一次专业隐患排查,是否建立隐患排查评审表；是否建立隐患排查评审表或隐患调查表。', '一般', 1),
('安全环保管理', '生产安全事故隐患管理', '隐患排查', '2.是否按要求组织进行隐患评审。是否按照隐患判定标准进行判定分级。是否建立重大/较大隐患风险评估报告。', '观察', 1),
('安全环保管理', '生产安全事故隐患管理', '隐患项目项目建议书编制、上报和立项', '3.经公司专业部门、二级单位评估确定需要投资进行治理的隐患，是否编制项目建议书报公司立项进行治理。', '观察', 1),
('安全环保管理', '生产安全事故隐患管理', '隐患管理', '4.二级单位是否将排查、评估出的隐患及治理情况向员工进行告知。不能立即整改和治理的隐患项目，是否制定有效管控和应急措施，并告知岗位人员和相关人员；是否存在其他未按制度要求执行的情况。', '一般', 1),
('安全环保管理', '生产安全事故隐患管理', '隐患项目销项', '5.隐患治理完成后，是否进行验收消项。', '观察', 1),
('安全环保管理', '生产安全事故隐患管理', '隐患项目督办', '6.对治理进度达不到要求的隐患项目，是否向责任单位下发隐患督办单并进行公示。', '观察', 1),
('安全环保管理', '事故事件管理', '事故报告', '1.发生事故事件后，是否按照制度要求上报。', '重要', 1),
('安全环保管理', '事故事件管理', '事故报告', '2.是否将发生的各类事故登记在事故台账内，事故事件资料齐全完好。是否按照四不放过要求开展具体工作；事故责任处理意见是否落实，并归档。', '一般', 1),
('安全环保管理', '事故事件管理', '事故分析分享', '3.是否对所管辖范围内的生产安全事件（包括承包商事件）进行分类统计、分析，制定防范措施。事故事件是否按照规定录入HSE信息系统。是否将典型的生产安全事故事件及时进行进行共享，吸取教训。对总部事故/事件通报是否及时进行传达学习，是否举一反三开展排查；是否存在其他未按制度要求执行的情况。', '观察', 1),
('安全环保管理', '应急管理', '机构及预案', '1.是否成立安全生产应急组织机构，明确分工和职责。是否成立应急预案编制修订工作组。应急预案是否覆盖单位的重大风险，应急处置是否科学有效合理。', '观察', 1),
