('安全环保管理', '应急管理', '应急演练', '4.是否按照公司制度规定频次组织应急演练。', '一般', 1),
('安全环保管理', '应急管理', '应急演练', '5.相关人员是否按计划参加基层单位应急演练观摩评审。是否建立应急演练记录、应急演练评审表。演练、响应过程存在的问题和缺陷是否整改。', '观察', 1),
('安全环保管理', '应急管理', '应急保障', '6.是否配置了满足单位应急处置所需要的应急物资器材。应急物资是否定点储存，统一标志；是否分类存放，码放整齐。是否建立应急物资台账，应急物资是否定期检查，是否完好、帐物相符。员工是否掌握应急物资的操作使用方法。', '观察', 1),
('安全环保管理', '应急管理', '安技装备管理', '7.是否在可能接触强腐蚀性物质（强酸、强碱等）和易经皮肤吸收的毒物的场所设置事故淋浴器及洗眼器。每天白班是否对事故淋浴器及洗眼器进行试验检查；事故淋浴器及洗眼器是否完好。', '重要', 1),
('安全环保管理', '应急管理', '安技装备管理', '8.是否按照制度要求配置急救箱。急救箱物品使用后，安全管理人员是否及时在使用台账上登记并上报事件。急救箱内的物品是否齐全有效。安全管理人员是否每季度对急救箱进行检查统计并及时更新。', '一般', 1),
('安全环保管理', '应急管理', '安技装备管理', '9.是否按照要求设置风向标。是否按要求建立风向标台账。现场风向标是否完好。管理人员是否每月对检查风向标的完好情况并及时检修、更换。', '一般', 1),
('安全环保管理', '应急管理', '安技装备管理', '10.是否按照制度要求配置便携式气体检测报警仪。是否建立便携式气体检测报警仪统计台帐。安全管理人员是否每周对便携式气体检测报警仪进行一次检查，确保完备好用。员工是否能够正确熟练使用便携式气体检测报警仪。便携式气体检测报警仪是否每年进行强制检定，粘贴检定标签、并提供检定报告。', '一般', 1),
