('安全环保管理', '应急管理', '安技装备管理', '12.火灾报警系统完好率、投用率是否达到100%。火灾报警系统每日是否进行自检试验，检查相关功能是否正常。火灾报警系统每季度是否进行动作试验；每年是否进行响应值试验。', '重要', 1),
('安全环保管理', '应急管理', '安技装备管理', '13.是否按照要求设置人体静电释放器。人体静电释放器是否完好，出现故障是否及时进行维修。人体静电释放器的接地电阻是否按要求纳入监测计划并进行检测。是否建立人体静电消除器管理台账。安全管理人员是否每周对人体静电消除器进行检查，确保完好。', '一般', 1),
