('安全环保管理', '消防管理', '档案与培训', '2.消控室操作人员是否按要求取得资格证书。岗位人员是否掌握各种消防设施的操作技能。', '重要', 1),
('安全环保管理', '消防管理', '消防设备设施', '3.临时占用消防通道是否按要求办理《石化公司厂区占路审批单》；消防通道、安全门是否畅通；固定式泡沫灭火系统是否每年须进行一次系统的完整性试验。消防水系统是否按要求定期进行出水试验。是否对固定、半固定泡沫灭火系统进行日常检查，扪盖是否齐全、阀门开关是否灵活。消防汽幕与平台连接是否牢固、可靠；消防汽幕是否畅通、无堵塞、泄漏现象，是否每年进行一次实际测试。 稳高压消防水压力是否≥0.7Mpa，消防泵联锁是否完好投用。消防设施、灭火器材是否按要求进行检查，是否完好。', '一般', 1),
