('安全环保管理', '检维修及作业许可管理', '进入受限空间作业', '6.进入受限空间作业是否提前预约。是否按要求办理受限空间作业许可证；签发程序是否正确，延期、有效期是否符合要求；票证是否有涂改、代签现象。是否开展作业前安全分析，是否制定风险削减措施。所有作业人、监护人及相关人员共同对风险消减措施的落实情况现场核查，确认合格，在相应栏目内签字。作业结束后是否验收清理现场、关闭许可证，并按要求归档保存。', '一般', 1),
('安全环保管理', '检维修及作业许可管理', '进入受限空间作业', '7.作业人员是否穿戴防静电服装；是否使用非防爆工具、机具。是否指定持证监护人。是否制定安全方案和应急预案；各类防护设施和救援物资是否配备到位。受限空间是否有安全警示标志；受限空间是否采取强制通风。是否登记作业人携入的工具、材料，作业结束后是否清点确认人员、工具和材料。进入有硫化亚铁产生的塔、容器（换热设备）、储罐等设备、容器作业前，是否制定落实防止硫化亚铁自燃的措施。进入受限空间作业前是否针对作业内容进行工作前安全分析，并制定作业安全措施。监护人和作业人员是否约定联络方式，作业前是否落实安全措施，确认人是否签字。', '一般', 1),
