('安全环保管理', '安全生产责任制', '有感领导', '6.是否定期深入基层进行安全生产监督检查。各级行政正职是否按要求讲授安全课。运行部（分厂）主要负责人是否主持HSE委员会会议。是否按规定要求在主持会议时带头开展安全经验分享。分厂和区域（车间）领导是否按规定参加班组安全学习。分厂和区域（车间）领导是否定期进行安全生产述职。', '观察', 2),
