('安全环保管理', '安全教育培训', '安全教育', '3.各级管理人员是否参加班组安全活动，班组安全学习频次和时间是否符合要求；安全活动是否有内容、有讨论、有记录、有检查、有评语；参加人是否与实际人员相符，缺席者是否进行补学；员工是否掌握近期安全活动记录内容；班组在班前会是否进行安全讲话；各级领导干部和管理人员是否利用安全观察与沟通，向员工讲解相关的安全制度规定等；日常会议、培训班、应急演练、班组安全活动、交接班前是否开展安全经验分享；是否存在其他未按制度要求执行的情况。', '观察', 2),
