('安全环保管理', '重大危险源和安全包保责任制管理', '重大危险源管理', '1.是否按照《重大危险源辨识》（GB18218）标准辨识确定重大危险源，是否按要求评估分级，并登记建档；重大危险源是否配备温度、压力、液位、流量、组分等信息的不间断采集系统及固定式气体检测报警装置；涉及毒性气体、液化气体、剧毒液体的一二级重大危险源是否设立SIS系统。', '重要', 2),
('安全环保管理', '管理与监控', '危险化学品重大危险源管理', '1.重大危险源是否建立健全安全监测监控体系，制定完善控制措施；是否按要求进行报告并录入HSE系统；是否定期全面检查重大危险源的安全状况；是否设置明显的安全警示标志和告知牌；是否将事故后果及应急措施告知周边人员；是否存在其他未按制度要求执行的情况。', '一般', 2),
