('安全环保管理', '管理措施', '危险化学品重大危险源安全包保责任制（安全生产承包点）管理办法', '2.公示牌是否写明重大危险源的主要负责人、技术负责人、操作负责人姓名、对应的安全包保职责及联系方式；在非重大危险源的安全生产承包点是否设立“安全生产承包点公示牌”；检查包保责任人（承包人）定期履职情况；是否存在其他未按制度要求执行的情况。', '观察', 2),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '1.危险化学品是否有符合相关规范要求的安全技术说明书与安全标签；危险化学品从业人员是否按要求取得相应资质。员工是否清楚日常安全使用、储存等要求，是否掌握消防、应急处置措施；在易燃、易爆场所禁止使用非防爆工具和移动通讯器具；是否存在其他未按制度要求执行的情况。', '一般', 2),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '2.是否建立危险化学品档案；是否编制危险化学品反应矩阵表。安全现状评价提出问题是否制定整改计划。安全现状评价提出问题是否按计划整改。是否对员工定期进行培训。员工是否了解和掌握学品危险特性；是否存在其他未按制度要求执行的情况。', '观察', 2),
('安全环保管理', '危险化学品安全管理', '危险化学品基本管理', '3.剧毒品是否对数量、流向、储存量和用途如实记录，并采取安保措施；危险化学品是否储存在专用仓库内，有专人管理，出入库时是否进行核查登记；性质相抵触、灭火方法不同的危险化学品是否分开存放；是否存在其他未按制度要求执行的情况。', '一般', 2),
('安全环保管理', '危险化学品安全管理', '防止硫化氢中毒安全管理', '4.有可能泄漏硫化氢造成中毒的装置或区域,是否安装固定式硫化氢报警仪，配备相应的应急器材及有效防护用具，并确保其完好备用；在含硫化氢的装置、设施、设备、管线区域附近是否设置醒目的硫化氢警示牌。', '一般', 2),
('安全环保管理', '危险化学品安全管理', '防硫化亚铁自燃安全管理', '5.易产生硫化亚铁的常压储罐，条件允许时是否设置氮封；易产生硫化亚铁的浮顶罐操作浮盘是否置底；易产生硫化亚铁的储罐是否按照规定及时切水；可能产生硫化亚铁的装置长期停工，是否采取加盲板密闭，注入氮气置换空气等措施，防止硫化亚铁的产生；易产生硫化亚铁的储罐呼吸阀、检尺采样孔等部位是否每半年清理一次；可能产生硫化亚铁的装置和场所是否制定防止硫化物自燃的措施；是否存在其他未按制度要求执行的情况。', '重要', 2),
('安全环保管理', '危险化学品安全管理', '危险化学品装卸安全管理', '6.进入装卸区域的车辆是否安装阻火器，对位后车头是否朝向出口方向；进站车辆车速是否在5公里/小时之内，是否携带杂物，进站车辆只允许乘坐司机和押运员两人；进站后是否按指定地点进行停放并熄火、用手闸制动；司机是否离开现场，有斜坡是否加固定块；装卸过程中是否严格执行岗位装卸操作规程；装卸人员和押运人员是否在现场；作业完毕封闭罐盖后是否静置不少于2分钟后拆除静电接地线；是否在站内乱排乱放、修理车辆；是否存在其他未按制度要求执行的情况。', '一般', 2),
('安全环保管理', '危险化学品装卸管理', '危险化学品安全管理', '1.易燃易爆介质装卸过程中是否使用防爆工具；是否使用非防爆通讯工具和非防爆电子产品；是否存在其他未按制度要求执行的情况。', '一般', 2),
