('安全环保管理', '生产安全事故隐患管理', '隐患项目项目建议书编制、上报和立项', '3.经公司专业部门、二级单位评估确定需要投资进行治理的隐患，是否编制项目建议书报公司立项进行治理。', '观察', 2),
('安全环保管理', '生产安全事故隐患管理', '隐患项目销项', '4.隐患治理完成后，是否进行验收消项。', '观察', 2),
