('安全环保管理', '生产安全事故隐患管理', '隐患管理', '6.二级单位是否将排查、评估出的隐患及治理情况向员工进行告知。不能立即整改和治理的隐患项目，是否制定有效管控和应急措施，并告知岗位人员和相关人员；是否存在其他未按制度要求执行的情况。', '一般', 2),
('安全环保管理', '隐患管理', '隐患治理', '1.是否将排查、评估出的隐患及治理情况向员工进行告知。不能立即整改和治理的隐患项目，是否制定有效管控和应急措施，并告知岗位人员和相关人员；是否存在其他未按制度要求执行的情况。', '一般', 2),
('安全环保管理', '事故事件管理', '事故报告', '1.发生事故事件后，是否按照制度要求上报。', '重要', 2),
('安全环保管理', '事故事件管理', '事故报告', '2.是否将发生的各类事故登记在事故台账内，事故事件资料齐全完好。是否按照四不放过要求开展具体工作；事故责任处理意见是否落实，并归档。', '一般', 2),
('安全环保管理', '事故事件管理', '事故分析分享', '3.是否对所管辖范围内的生产安全事件（包括承包商事件）进行分类统计、分析，制定防范措施。事故事件是否按照规定录入HSE信息系统。是否将典型的生产安全事故事件及时进行进行共享，吸取教训。对总部事故/事件通报是否及时进行传达学习，是否举一反三开展排查；是否存在其他未按制度要求执行的情况。', '观察', 2),
('安全环保管理', '应急管理', '机构及预案', '1.是否成立安全生产应急组织机构，明确分工和职责。是否成立应急预案编制修订工作组。应急预案是否覆盖单位的重大风险，应急处置是否科学有效合理。', '观察', 2),
