('安全环保管理', '应急管理', '应急演练', '5.相关人员是否按计划参加基层单位应急演练观摩评审。是否建立应急演练记录、应急演练评审表。演练、响应过程存在的问题和缺陷是否整改；是否存在其他未按制度要求执行的情况。', '观察', 2),
