('安全环保管理', '应急管理', '安技装备管理', '7.是否在可能接触强腐蚀性物质（强酸、强碱等）和易经皮肤吸收的毒物的场所设置事故淋浴器及洗眼器。每天白班是否对事故淋浴器及洗眼器进行试验检查；事故淋浴器及洗眼器是否完好。', '重要', 2),
